const body = $input.first().json.body;

if (!body?.entry?.[0]) {
  return [{ json: { skip: true } }];
}

const value = body.entry[0].changes?.[0]?.value;

if (!value?.messages?.[0]) {
  return [{ json: { skip: true } }];
}

const message = value.messages[0];
const contact = value.contacts?.[0];
const msgType = message.type;

let messageText = '';

if (msgType === 'text') {
  messageText = message.text.body;
} else if (msgType === 'audio') {
  messageText = '[El cliente envió un audio. Responde amablemente que por el momento solo puedes procesar texto.]';
} else if (msgType === 'image') {
  messageText = '[El cliente envió una imagen. Responde amablemente que por el momento solo puedes procesar texto.]';
} else if (msgType === 'document') {
  messageText = '[El cliente envió un documento. Responde amablemente que por el momento solo puedes procesar texto.]';
} else if (msgType === 'interactive') {
  if (message.interactive?.type === 'button_reply') {
    messageText = message.interactive.button_reply.title;
  } else if (message.interactive?.type === 'list_reply') {
    messageText = message.interactive.list_reply.title;
  } else {
    return [{ json: { skip: true } }];
  }
} else {
  return [{ json: { skip: true } }];
}

return [{
  json: {
    skip: false,
    phone: message.from,
    name: contact?.profile?.name ?? 'Cliente',
    message: messageText,
    messageType: msgType,
    messageId: message.id,
    phoneNumberId: value.metadata.phone_number_id,
    timestamp: message.timestamp
  }
}];

const rawOutput = $input.first().json.output ?? '';

// Detectar etiquetas de estado del lead
const isLead    = rawOutput.includes('##LEAD##');
const isPosible = rawOutput.includes('##POSIBLE##');
const isPerdido = rawOutput.includes('##PERDIDO##');

// Limpiar respuesta de etiquetas
const respuesta = rawOutput
  .replace('##LEAD##', '')
  .replace('##POSIBLE##', '')
  .replace('##PERDIDO##', '')
  .trim();

// Determinar estado
let leadStatus = null;
if (isLead)    leadStatus = 'qualified';
else if (isPosible) leadStatus = 'potential';
else if (isPerdido) leadStatus = 'lost';

const hasLeadEvent = isLead || isPosible || isPerdido;

// Preparar mensaje de notificación para el owner
const statusLabel = leadStatus === 'qualified' ? '✅ Calificado'
  : leadStatus === 'potential' ? '🟡 Posible'
  : '❌ Perdido';

const statusEmoji = leadStatus === 'qualified' ? '✅'
  : leadStatus === 'potential' ? '🟡'
  : '❌';

const phone   = $('Extraer Mensaje').item.json.phone;
const name    = $('Extraer Mensaje').item.json.name;
const message = $('Extraer Mensaje').item.json.message;
const preview = message.substring(0, 120);

const notifMsg = hasLeadEvent
  ? `🔔 *Nuevo evento de lead ${statusEmoji}*\n\n👤 ${name}\n📱 +${phone}\n📊 Estado: ${statusLabel}\n💬 "${preview}"\n\n_Avaxon CRM 🤖_`
  : '';

return [{
  json: {
    respuesta,
    isLead,
    isPosible,
    isPerdido,
    leadStatus,
    hasLeadEvent,
    notifMsg,
    phone,
    name,
    message,
    phoneNumberId: $('Extraer Mensaje').item.json.phoneNumberId
  }
}];

const rows = $input.all();

// Fecha de hoy en zona horaria México (UTC-6)
const mexicoDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Mexico_City'
}).format(new Date()); // Resultado: YYYY-MM-DD

const stats = {
  fecha_reporte: mexicoDate,
  total: 0,
  qualified: 0,
  potential: 0,
  lost: 0,
  qualified_list: [],
  potential_list: [],
  lost_list: []
};

for (const row of rows) {
  const data = row.json;
  // Filtrar solo filas de hoy
  if (!data.fecha || !String(data.fecha).startsWith(mexicoDate)) continue;

  stats.total++;
  const display = (data.name && data.name !== 'Cliente')
    ? `${data.name} (+${data.phone})`
    : `+${data.phone}`;

  if (data.status === 'qualified') {
    stats.qualified++;
    stats.qualified_list.push(display);
  } else if (data.status === 'potential') {
    stats.potential++;
    stats.potential_list.push(display);
  } else if (data.status === 'lost') {
    stats.lost++;
    stats.lost_list.push(display);
  }
}

return [{ json: stats }];

const {
  fecha_reporte, total,
  qualified, potential, lost,
  qualified_list, potential_list, lost_list
} = $input.first().json;

// YYYY-MM-DD → DD/MM/YYYY
const [year, month, day] = fecha_reporte.split('-');
const fechaDisplay = `${day}/${month}/${year}`;

const lines = [
  `📊 *REPORTE DIARIO*`,
  `📅 ${fechaDisplay}`,
  `_Agente WhatsApp — Suplementos_`,
  ``
];

lines.push(`✅ *Leads Ganados: ${qualified}*`);
if (qualified_list.length > 0) {
  qualified_list.forEach(n => lines.push(`   • ${n}`));
}

lines.push(``);
lines.push(`🟡 *Prospectos Posibles: ${potential}*`);
if (potential_list.length > 0) {
  potential_list.forEach(n => lines.push(`   • ${n}`));
}

lines.push(``);
lines.push(`❌ *Leads Perdidos: ${lost}*`);
if (lost_list.length > 0) {
  lost_list.forEach(n => lines.push(`   • ${n}`));
}

lines.push(``);
lines.push(`━━━━━━━━━━━━━━━━`);
lines.push(`📱 *Total conversaciones hoy: ${total}*`);

if (total === 0) {
  lines.push(``);
  lines.push(`_Sin actividad registrada hoy._`);
}

lines.push(``);
lines.push(`🤖 _Enviado por Avaxon_`);

return [{ json: { reporte: lines.join('\n') } }];
